// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Restrict seed to a reasonable range to avoid overflow of pot
        seed = bound(seed, 0, 1e18);

        // Fund the contract with some ether to allow transfers
        vm.deal(address(c), 10 ether);

        // Call play with exactly the ticket amount
        c.play{value: 10}();

        // After play, pot must be either 0 (payout happened) or >= 10 (no payout)
        uint256 potAfter = c.pot();
        assertTrue(potAfter == 0 || potAfter >= 10);
    }
}

